    if (!this.peerUndoStacks.has(peerId)) {
      this.peerUndoStacks.set(peerId, []);
    }
    this.peerUndoStacks.get(peerId)!.push(prevElements.map(e => ({ ...e })));
    this.peerRedoStacks.set(peerId, []);
  }

  public undo(peerId: string): WhiteboardElement[] {
    const undoList = this.peerUndoStacks.get(peerId);
    if (!undoList || undoList.length === 0) {
      if (this.undoStack.length > 0) {
