  private ctx: any;
  private stateManager: CanvasStateManager;
  private vp: ViewportTransform = { zoom: 1, panX: 0, panY: 0 };
  constructor(ctx: any, sm: CanvasStateManager) {
    this.ctx = ctx;
    this.stateManager = sm;
  }
  public render(): void {
    const elements = this.stateManager.getAllElements();
    for (const el of elements) {
      this.ctx.strokeStyle = el.stroke;
      if (el.type === "rect") this.ctx.strokeRect(el.x, el.y, el.width, el.height);
    }
  }

  public computeDirtyBounds(before: WhiteboardElement[], after: WhiteboardElement[]): { minX: number; minY: number; maxX: number; maxY: number } {
    return CanvasRenderer.computeDirtyBounds(before, after);
  }

  public static computeDirtyBounds(before: WhiteboardElement[], after: WhiteboardElement[]): { minX: number; minY: number; maxX: number; maxY: number } {
    const beforeMap = new Map<string, WhiteboardElement>();
    for (const el of before) beforeMap.set(el.id, el);

    const afterMap = new Map<string, WhiteboardElement>();
    for (const el of after) afterMap.set(el.id, el);

    let hasDirty = false;
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;

    const includeBox = (el: WhiteboardElement) => {
      hasDirty = true;
      const x1 = Math.min(el.x, el.x + el.width);
      const y1 = Math.min(el.y, el.y + el.height);
      const x2 = Math.max(el.x, el.x + el.width);
      const y2 = Math.max(el.y, el.y + el.height);
      if (x1 < minX) minX = x1;
      if (y1 < minY) minY = y1;
      if (x2 > maxX) maxX = x2;
      if (y2 > maxY) maxY = y2;
    };

    for (const [id, bEl] of beforeMap.entries()) {
      const aEl = afterMap.get(id);
      if (!aEl) {
        includeBox(bEl);
      } else if (
        bEl.x !== aEl.x ||
        bEl.y !== aEl.y ||
        bEl.width !== aEl.width ||
        bEl.height !== aEl.height ||
        bEl.stroke !== aEl.stroke ||
        bEl.type !== aEl.type ||
        bEl.version !== aEl.version
      ) {
        includeBox(bEl);
        includeBox(aEl);
      }
    }

    for (const [id, aEl] of afterMap.entries()) {
      if (!beforeMap.has(id)) {
        includeBox(aEl);
      }
    }

    if (!hasDirty) {
      return { minX: 0, minY: 0, maxX: 0, maxY: 0 };
    }

    return { minX, minY, maxX, maxY };
  }
}

